import {safe} from './experience.js';
export function personalBoard(albums){const a=albums.find(a=>a.id==='anatole-muster-hopecore');return `<section class="personal-heading"><span class="eyebrow">SOBRE / MEETING.POINTS</span><h1>Lucas Egydio<span>em alguns pontos.</span></h1><p>Discos, imagens e opiniões. Um arquivo pessoal que continua mudando.</p></section><section class="personal-board" aria-label="Referências pessoais de Lucas"><div class="personal-orbits" aria-hidden="true"><i></i><i></i><i></i></div><article class="personal-card personal-identity"><button class="personal-handle" aria-label="Mover cartão Lucas Egydio">LUCAS EGYDIO <span aria-hidden="true">⠿</span></button><strong class="personal-monogram">le.</strong><p>O ponto de partida é a escuta.<br>O resto se encontra por aqui.</p><a href="https://www.instagram.com/lucasegydio/" target="_blank" rel="noopener noreferrer">@lucasegydio ↗</a></article><article class="personal-card personal-origin"><button class="personal-handle" aria-label="Mover cartão Origem">DE ONDE VEIO <span aria-hidden="true">⠿</span></button><strong>2025 →</strong><p>A ideia começou no Visioncraft Music. Agora, som, imagem e texto dividem o mesmo espaço.</p><details><summary>A primeira review +</summary><p>hopecore, de Anatole Muster, foi o primeiro texto real trazido para este arquivo.</p><a href="#album/anatole-muster-hopecore">Ler a review ↗</a></details></article><article class="personal-card personal-record"><button class="personal-handle" aria-label="Mover cartão hopecore">UM DISCO, UM COMEÇO <span aria-hidden="true">⠿</span></button>${a?`<a href="#album/${a.id}"><img src="${safe(a.cover)}" alt="Capa de hopecore"><strong>hopecore</strong><span>Anatole Muster ↗</span></a>`:''}</article><div class="personal-board-caption"><span>MEETING.POINTS — ARQUIVO PESSOAL</span><button data-reset-board>Recompor ↻</button></div></section><section class="personal-paths"><a href="#arquivo"><span>O que eu escuto</span>Reviews ↗</a><a href="#moods"><span>O que eu vejo</span>Moods ↗</a><a href="#tv"><span>O que eu compartilho</span>TV ↗</a></section>`;}
let dispose=()=>{};
export function bindPersonalBoard(root){dispose();const board=root.querySelector('.personal-board');if(!board)return;const events=new AbortController(),opt={signal:events.signal},reduce=matchMedia('(prefers-reduced-motion: reduce)');let z=2;
 const reset=()=>board.querySelectorAll('.personal-card').forEach(c=>{c.style.setProperty('--drag-x','0px');c.style.setProperty('--drag-y','0px');c.style.zIndex='';});
 board.querySelector('[data-reset-board]').addEventListener('click',reset,opt);
 board.addEventListener('pointermove',e=>{if(reduce.matches)return;const r=board.getBoundingClientRect();board.style.setProperty('--orbit-x',((e.clientX-r.left)/r.width-.5)*28+'px');board.style.setProperty('--orbit-y',((e.clientY-r.top)/r.height-.5)*28+'px');},opt);
 board.addEventListener('pointerleave',()=>{board.style.setProperty('--orbit-x','0px');board.style.setProperty('--orbit-y','0px');},opt);
 board.querySelectorAll('.personal-card').forEach(card=>{const handle=card.querySelector('.personal-handle');let drag=null;const pos=()=>({x:parseFloat(card.style.getPropertyValue('--drag-x'))||0,y:parseFloat(card.style.getPropertyValue('--drag-y'))||0});const move=(x,y)=>{const p=pos(),r=card.getBoundingClientRect(),b=board.getBoundingClientRect();card.style.setProperty('--drag-x',Math.max(p.x+b.left-r.left+10,Math.min(p.x+b.right-r.right-10,x))+'px');card.style.setProperty('--drag-y',Math.max(p.y+b.top-r.top+10,Math.min(p.y+b.bottom-r.bottom-48,y))+'px');};
 handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={...pos(),px:e.clientX,py:e.clientY};handle.setPointerCapture(e.pointerId);card.style.zIndex=String(++z);},opt);
 handle.addEventListener('pointermove',e=>{if(drag)move(drag.x+e.clientX-drag.px,drag.y+e.clientY-drag.py);},opt);
 const end=()=>{drag=null;};handle.addEventListener('pointerup',end,opt);handle.addEventListener('pointercancel',end,opt);handle.addEventListener('lostpointercapture',end,opt);
 handle.addEventListener('keydown',e=>{const d={ArrowLeft:[-12,0],ArrowRight:[12,0],ArrowUp:[0,-12],ArrowDown:[0,12]}[e.key];if(d){e.preventDefault();const p=pos();move(p.x+d[0],p.y+d[1]);}},opt);
 });const resize=new ResizeObserver(reset);resize.observe(board);dispose=()=>{events.abort();resize.disconnect();};
}
